// ═══════ Seeded RNG ═══════
function rng(seed) {
  let v = seed;
  return () => { v = (v * 16807) % 2147483647; return (v - 1) / 2147483646; };
}

// ═══════ Bake starfield ═══════
function bakeStarfield(w, h) {
  const cv = document.createElement("canvas");
  cv.width = w; cv.height = h;
  const c = cv.getContext("2d");
  c.fillStyle = "#000000"; c.fillRect(0, 0, w, h);
  const R = rng(42);
  for (let i = 0; i < 4000; i++) {
    const x = R() * w, y = R() * h, br = R() * 0.4 + 0.08;
    const sz = R() < 0.03 ? 1.8 : R() < 0.15 ? 1.0 : 0.5;
    c.beginPath(); c.arc(x, y, sz, 0, Math.PI * 2);
    const t = R();
    c.fillStyle = t<0.3?`rgba(170,190,235,${br})`:t<0.4?`rgba(250,220,175,${br})`:`rgba(205,210,220,${br})`;
    c.fill();
  }
  return cv;
}

// ═══════ 8 distinct territory heatmaps — per-tier bounds, resolution, and zone data ═══════
function fField(px,py,faction,zones) {
  let t=0;
  for(const z of zones){
    if(z.f!==faction) continue;
    const d=Math.sqrt((px-z.x)**2+(py-z.y)**2);
    t += z.str*Math.exp(-(d*d)/(2*z.sp*z.sp));
  }
  return t;
}
function bakeHeatmap(tier) {
  const {x0,y0,w,h,res,zones,aMul=150}=tier;
  const pw=Math.round(w*res), ph=Math.round(h*res);
  const cv=document.createElement("canvas"); cv.width=pw; cv.height=ph;
  const ctx=cv.getContext("2d"), img=ctx.createImageData(pw,ph), d=img.data;
  for(let py=0;py<ph;py++){
    for(let px=0;px<pw;px++){
      const wx=x0+px/res, wy=y0+py/res;
      const ei=fField(wx,wy,"empire",zones), fi=fField(wx,wy,"federation",zones);
      const tot=ei+fi; if(tot<0.02) continue;
      const dom=(ei-fi)/tot, int=Math.min(tot*1.2,1.0);
      let r,g,b;
      if(dom>0.35){const t=Math.min((dom-0.35)/0.45,1.0);r=Math.round(140+40*t);g=Math.round(45-15*t);b=Math.round(120-80*t);}
      else if(dom<-0.35){const t=Math.min((-dom-0.35)/0.45,1.0);r=Math.round(140-100*t);g=Math.round(45+70*t);b=Math.round(120+80*t);}
      else{r=140;g=45;b=120;}
      const idx=(py*pw+px)*4;
      d[idx]=r;d[idx+1]=g;d[idx+2]=b;d[idx+3]=Math.min(255,Math.round(int*aMul));
    }
  }
  ctx.putImageData(img,0,0); return cv;
}

