// ═══════════════════════════════════════
// MAIN COMPONENT
// ═══════════════════════════════════════
export default function GalaxyMap() {
  const cvRef = useRef(null);
  const [hov, setHov] = useState(null);
  const [sel, setSel] = useState(null);
  const [ready, setReady] = useState(false);

  const cam = useRef({ z:1, px:0, py:0 });
  const drg = useRef({ on:false, sx:0, sy:0, spx:0, spy:0, mv:false });
  const starBuf = useRef(null);
  const terrTiers = useRef([]);
  const galBaseCv = useRef(null);
  const galImgRef = useRef(null);

  // ─── Init: load embedded image + bake buffers ───
  useEffect(() => {
    starBuf.current = bakeStarfield(VW*2, VH*2);
    terrTiers.current = TERR_TIERS.map(t => ({ maxZ:t.maxZ, hm:t.hm, a:t.a, gal:t.gal, cv:bakeHeatmap(t.hm) }));
    galBaseCv.current = bakeHeatmap(HM_GAL);
    const img = new Image();
    img.onload = () => { galImgRef.current = img; setReady(true); };
    img.src = GAL_IMG;
  }, []);

  // ─── Render ───
  const render = useCallback(() => {
    const cv = cvRef.current; if(!cv) return;
    const c = cv.getContext("2d");
    cv.width = VW*2; cv.height = VH*2; c.scale(2,2);
    const { z, px, py } = cam.current;

    c.fillStyle = "#000000"; c.fillRect(0,0,VW,VH);

    c.save();
    c.translate(VW/2+px, VH/2+py);
    c.scale(z,z);
    c.translate(-VW/2, -VH/2);

    // L1: Starfield background
    if(starBuf.current) c.drawImage(starBuf.current, 0,0,VW*2,VH*2, 0,0,VW,VH);

    // L2: NASA Galaxy image (embedded)
    if(galImgRef.current) {
      c.save();
      c.globalAlpha = 0.92;
      const half = IMG_SZ/2;
      c.drawImage(galImgRef.current, IMG_CX-half, IMG_CY-half, IMG_SZ, IMG_SZ);
      c.restore();
    }

    // L3: Territory heatmap (8 tiers — different spatial scale per zoom level)
    if(terrTiers.current.length) {
      const tier = terrTiers.current.find(t => z <= t.maxZ) || terrTiers.current[terrTiers.current.length-1];
      // For T6-T8: draw galaxy base layer first so territory is visible across entire galaxy
      if(tier.gal && galBaseCv.current) {
        c.save();
        c.globalAlpha = tier.a * 0.7;
        c.drawImage(galBaseCv.current, HM_GAL.x0, HM_GAL.y0, HM_GAL.w, HM_GAL.h);
        c.restore();
      }
      // Then draw the zoom-appropriate detail layer on top
      c.save();
      c.globalAlpha = tier.a || 0.55;
      c.drawImage(tier.cv, tier.hm.x0, tier.hm.y0, tier.hm.w, tier.hm.h);
      c.restore();
    }

    // L3.5: Distance rings from Sol (zoom-adaptive, linear scale)
    if(z > 1) {
      const SOL_X = 400, SOL_Y = 558;
      // Linear scale: Pleiades at 444 ly = 65.15 map units from Sol
      const MU_PER_LY = 65.15 / 444; // 0.14674
      const lyToR = (ly) => ly * MU_PER_LY;
      let rings;
      if(z < 5) rings = [100, 500, 1000];
      else if(z < 25) rings = [15, 50, 100];
      else rings = [5, 10, 15, 20];
      const s = 1/z;
      c.save();
      rings.forEach(ly => {
        const r = lyToR(ly);
        c.beginPath();
        c.arc(SOL_X, SOL_Y, r, 0, Math.PI*2);
        c.strokeStyle = "rgba(255,255,255,0.45)";
        c.lineWidth = s * 1.8;
        c.setLineDash([s*4, s*4]);
        c.stroke();
        c.setLineDash([]);
        c.fillStyle = "rgba(255,255,255,0.7)";
        const fSize = z < 5 ? s*15 : s*10;
        c.font = `bold ${fSize}px monospace`;
        c.textAlign = "center";
        c.fillText(ly + " ly", SOL_X, SOL_Y - r - s*3);
      });
      c.restore();
    }

    // L4: Map labels
    drawLabels(c, z);

    // L5: Star systems
    drawSystems(c, hov, z);

    c.restore();

    // HUD overlay (screen-space)
    drawHUD(c, z);
  }, [hov, ready]);

  useEffect(() => { render(); }, [render]);

  // ─── Labels (directional markers only) ───
  function drawLabels(c, z) {
    const s = 1/z;
    c.textAlign = "center";

    // Directional markers
    c.fillStyle = "rgba(200,210,230,0.25)";
    c.font = `${8*s}px "Courier New",monospace`;
    c.save(); c.translate(425,548); c.rotate(-0.8);
    c.fillText("COREWARD \u2197", 0, 0); c.restore();
    c.save(); c.translate(385,578); c.rotate(-0.8);
    c.fillText("\u2199 RIMWARD", 0, 0); c.restore();
  }

  // ─── Systems (visible at 20x zoom) ───
  function drawSystems(c, hovId, z) {
    if(z < 20) return;
    const s = 1/z;
    const fadeIn = Math.min(1, (z - 20) / 5); // fade in from 20x to 25x

    SYSTEMS.forEach(sys => {
      const isH = hovId === sys.id;
      const pal = CLR[sys.f] || CLR.unknown;
      const dotSz = (isH ? sys.sz+1.2 : sys.sz) * s * 0.55;
      const glR = dotSz * 3.5;

      c.save();
      c.globalAlpha = isH ? 1.0 : fadeIn;

      // Glow
      const g = c.createRadialGradient(sys.x,sys.y,0,sys.x,sys.y,glR);
      g.addColorStop(0, pal.glow+(isH?"0.55)":"0.3)"));
      g.addColorStop(1, "rgba(0,0,0,0)");
      c.beginPath(); c.arc(sys.x,sys.y,glR,0,Math.PI*2); c.fillStyle=g; c.fill();

      // Dot
      c.beginPath(); c.arc(sys.x,sys.y,dotSz,0,Math.PI*2);
      c.fillStyle = pal.dot; c.fill();
      if(isH) { c.strokeStyle="#fff"; c.lineWidth=1*s; c.stroke(); }

      // Label
      const fs = (isH ? 14 : sys.id==="sol" ? 14 : 12) * s;
      c.font = `bold ${fs}px "Courier New",monospace`;
      c.fillStyle = isH ? "#fff" : "rgba(220,220,220,0.85)";
      c.textAlign = "left";
      c.fillText(sys.n, sys.x + dotSz + 2.5*s, sys.y + 2*s);

      c.restore();
    });
  }

  // ─── HUD ───
  function drawHUD(c, z) {
    const lx=12, ly=12;
    c.fillStyle="rgba(5,5,12,0.92)";c.strokeStyle="rgba(80,90,130,0.3)";c.lineWidth=1;
    c.beginPath();c.roundRect(lx,ly,200,136,6);c.fill();c.stroke();

    c.font='bold 10px "Courier New",monospace';c.fillStyle="#99a";c.textAlign="left";
    c.fillText("TERRITORY LEGEND",lx+14,ly+18);

    [{c:CLR.empire.dot,l:"Annunaki Empire"},{c:CLR.federation.dot,l:"Galactic Federation"},
     {c:CLR.contested.dot,l:"Contested / Frontier"},{c:CLR.neutral.dot,l:"Neutral / Independent"},
     {c:CLR.unknown.dot,l:"Unknown / Unaligned"}].forEach((it,i) => {
      const iy=ly+36+i*19;
      c.beginPath();c.arc(lx+20,iy,4,0,Math.PI*2);c.fillStyle=it.c;c.fill();
      c.font='9px "Courier New",monospace';c.fillStyle="rgba(200,200,210,0.8)";
      c.fillText(it.l,lx+32,iy+3);
    });

    c.fillStyle="rgba(5,5,12,0.8)";c.strokeStyle="rgba(80,90,130,0.25)";
    c.beginPath();c.roundRect(VW-150,12,138,36,5);c.fill();c.stroke();
    c.font='9px "Courier New",monospace';c.fillStyle="rgba(180,180,200,0.65)";c.textAlign="left";
    c.fillText(`ZOOM: ${z.toFixed(1)}x`,VW-140,28);
    c.fillStyle="rgba(140,140,160,0.45)";
    c.fillText("Scroll \u00b7 Drag \u00b7 Dbl-click",VW-140,42);

    c.font='bold 15px "Courier New",monospace';c.fillStyle="rgba(200,210,230,0.85)";c.textAlign="center";
    c.fillText("ARCANUM \u2014 GALACTIC TERRITORY MAP",VW/2,VH-18);
    c.font='8px "Courier New",monospace';c.fillStyle="rgba(140,150,170,0.45)";
    c.fillText("Milky Way \u00b7 Schematic directions and galactic backdrop \u00b7 Local rings show radial ly",VW/2,VH-6);
  }

  // ─── Input ───
  const s2m = useCallback(e => {
    const cv=cvRef.current; if(!cv) return null;
    const r=cv.getBoundingClientRect();
    const sx=(e.clientX-r.left)*(VW/r.width), sy=(e.clientY-r.top)*(VH/r.height);
    const{z,px,py}=cam.current;
    return { mx:(sx-VW/2-px)/z+VW/2, my:(sy-VH/2-py)/z+VH/2 };
  },[]);

  const findSys = useCallback((mx,my) => {
    const z=cam.current.z;
    if(z < 20) return null;
    let best=null, bestD=Infinity;
    const maxR = (6/Math.max(z,0.5))+2;
    for(const sys of SYSTEMS){
      const d=Math.hypot(mx-sys.x,my-sys.y);
      if(d < maxR && d < bestD){ bestD=d; best=sys; }
    }
    return best;
  },[]);

  const onW = useCallback(e => {
    e.preventDefault();
    const cm=cam.current, f=e.deltaY>0?0.88:1.14;
    const nz=Math.max(0.4,Math.min(MAX_ZOOM,cm.z*f));
    const cv=cvRef.current; if(!cv) return;
    const r=cv.getBoundingClientRect();
    const sx=(e.clientX-r.left)*(VW/r.width), sy=(e.clientY-r.top)*(VH/r.height);
    const wx=(sx-VW/2-cm.px)/cm.z, wy=(sy-VH/2-cm.py)/cm.z;
    cm.z=nz; cm.px=sx-VW/2-wx*nz; cm.py=sy-VH/2-wy*nz;
    render();
  },[render]);

  const onPD = useCallback(e => {
    drg.current={on:true,sx:e.clientX,sy:e.clientY,spx:cam.current.px,spy:cam.current.py,mv:false};
    e.currentTarget.setPointerCapture(e.pointerId);
  },[]);

  const onPM = useCallback(e => {
    const co=s2m(e); if(co){const sy=findSys(co.mx,co.my);setHov(sy?sy.id:null);}
    const d=drg.current; if(!d.on) return;
    const cv=cvRef.current; if(!cv) return;
    const r=cv.getBoundingClientRect();
    const dx=(e.clientX-d.sx)*(VW/r.width), dy=(e.clientY-d.sy)*(VH/r.height);
    if(Math.abs(dx)+Math.abs(dy)>3) d.mv=true;
    cam.current.px=d.spx+dx; cam.current.py=d.spy+dy;
    render();
  },[s2m,findSys,render]);

  const onPU = useCallback(e => {
    const d=drg.current; d.on=false;
    if(!d.mv){const co=s2m(e);if(co){const sy=findSys(co.mx,co.my);setSel(sy||null);}}
  },[s2m,findSys]);

  const onDbl = useCallback(()=>{cam.current={z:1,px:0,py:0};render();},[render]);
  const zTo = useCallback((z,fx,fy)=>{cam.current.z=z;cam.current.px=(VW/2-fx)*z;cam.current.py=(VH/2-fy)*z;render();},[render]);

  const fL=f=>({empire:"ANNUNAKI EMPIRE",federation:"GALACTIC FEDERATION",contested:"CONTESTED",neutral:"INDEPENDENT"}[f]||"UNKNOWN");
  const gc=f=>(CLR[f]||CLR.unknown).dot;

  return (
    <div style={{background:"#000000",width:"100%",minHeight:"100vh",fontFamily:'"Courier New",monospace',color:"#ccd"}}>
      <div style={{display:"flex",justifyContent:"center",gap:6,padding:"10px 8px 4px",flexWrap:"wrap"}}>
        {PRESETS.map(p=>(
          <button key={p.l} onClick={()=>zTo(p.z,p.x,p.y)}
            style={{background:"rgba(10,10,25,0.85)",border:"1px solid rgba(80,90,130,0.35)",color:"#88a",padding:"5px 12px",borderRadius:4,cursor:"pointer",fontFamily:"inherit",fontSize:10,letterSpacing:0.5}}
            onMouseEnter={e=>{e.target.style.borderColor="#88a";e.target.style.color="#dde";}}
            onMouseLeave={e=>{e.target.style.borderColor="rgba(80,90,130,0.35)";e.target.style.color="#88a";}}
          >{p.l}</button>
        ))}
      </div>

      <div style={{display:"flex",justifyContent:"center",padding:"4px 8px"}}>
        <canvas ref={cvRef}
          style={{width:"100%",maxWidth:1000,height:"auto",aspectRatio:`${VW}/${VH}`,
            cursor:drg.current.on?"grabbing":hov?"pointer":"grab",
            borderRadius:6,border:"1px solid rgba(80,90,130,0.2)",touchAction:"none"}}
          onWheel={onW} onPointerDown={onPD} onPointerMove={onPM} onPointerUp={onPU} onDoubleClick={onDbl} />
      </div>

      {sel && (
        <div style={{margin:"8px auto",maxWidth:720,background:"rgba(8,8,18,0.95)",border:`1px solid ${gc(sel.f)}44`,borderRadius:8,padding:"14px 18px",position:"relative"}}>
          <button onClick={()=>setSel(null)} style={{position:"absolute",top:10,right:12,background:"none",border:"1px solid rgba(80,90,130,0.3)",color:"#666",borderRadius:4,padding:"1px 7px",cursor:"pointer",fontFamily:"inherit",fontSize:11}}>{"\u2715"}</button>
          <div style={{fontSize:13,fontWeight:"bold",color:gc(sel.f),marginBottom:4}}>{sel.lbl}</div>
          <div style={{fontSize:10.5,color:"rgba(200,200,215,0.7)",lineHeight:1.65,maxWidth:640}}>{sel.d}</div>
          <div style={{fontSize:8,color:"rgba(140,140,160,0.4)",marginTop:8,textTransform:"uppercase",letterSpacing:1}}>Faction: {fL(sel.f)}</div>
        </div>
      )}

      <div style={{margin:"4px auto 16px",maxWidth:720,padding:"10px 14px",background:"rgba(8,8,18,0.55)",border:"1px solid rgba(80,90,130,0.12)",borderRadius:5,fontSize:9.5,lineHeight:1.65,color:"rgba(150,160,185,0.5)",textAlign:"center"}}>
        The Annunaki Empire (red) controls territory across the galaxy, strongest near Sol.
        Federation islands (blue) are gate-connected enclaves throughout Imperial space.
        Local markers follow lore bible v7: grey means independent, dark teal means unconfirmed occupancy.
        Regional colour shows broad influence, not ownership of every system. Sector radius: 1,000 ly; subsector: 100 ly.
        Directions and galaxy-wide territorial boundaries are schematic; local radial distances are calibrated.
        <span style={{display:"block",marginTop:4,fontStyle:"italic",opacity:0.7}}>
          Scroll to zoom \u00b7 Drag to pan \u00b7 Double-click to reset \u00b7 Click systems for details
        </span>
      </div>
    </div>
  );
}
